mapper.delete:
BEGIN
  DELETE FROM yrt_detail
   WHERE yrt_id IN (
     SELECT yrt_id FROM yrt_header
      WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId})
        AND base_year = #{baseYear}
        AND confirm_yn = 'N'
   );

  DELETE FROM yrt_result_total
   WHERE yrt_id IN (
     SELECT yrt_id FROM yrt_header
      WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId})
        AND base_year = #{baseYear}
        AND confirm_yn = 'N'
   );

  DELETE FROM yrt_header
   WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId})
     AND base_year = #{baseYear}
     AND confirm_yn = 'N';
END;

BEGIN
  DELETE FROM yrt_detail       WHERE yrt_id = #{yrtId};
  DELETE FROM yrt_result_total WHERE yrt_id = #{yrtId};
  DELETE FROM yrt_header       WHERE yrt_id = #{yrtId} AND confirm_yn = 'N';
END;
